import assert from 'node:assert/strict'; import SuperJSON from './dist/index.js';
const s=new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',sanitizeMessage:true}}); s.allowErrorProps('stackFrames'); const e=new Error('https://example.com',{cause:new Error('a@b.com')}); e.stack='Error: x\n    at /tmp/a.js:1:2'; const r=s.serialize(e); assert.equal(r.meta.values[0],'Error/frames'); assert.equal(r.json.stackFrames[1].raw,'at /tmp/a.js:1:2'); assert.equal(r.json.cause.message,'[redacted]'); const out=s.parse(s.stringify(new Map([['x',e]]))); assert.equal(out.get('x').stackFrames[1].raw,'at /tmp/a.js:1:2'); assert(out.get('x').cause instanceof Error); console.log('focused reproduction passed');
